const seasonFixtures = `-- name: SeasonFixtures :many
SELECT m.number AS matchday, f.id, f.kickoff, f.status, f.exception,
       h.id AS home_id, h.name AS home_name, a.id AS away_id, a.name AS away_name
FROM matchdays m
JOIN fixtures f ON f.matchday_id = m.id
JOIN teams h ON h.id = f.home_team_id
JOIN teams a ON a.id = f.away_team_id
WHERE m.season_id = $1
ORDER BY m.number, f.kickoff, f.id
`

type SeasonFixturesRow struct {
	Matchday  int32
	ID        uuid.UUID
	Kickoff   *time.Time
	Status    string
	Exception string
	HomeID    uuid.UUID
	HomeName  string
	AwayID    uuid.UUID
	AwayName  string
}

func (q *Queries) SeasonFixtures(ctx context.Context, seasonID uuid.UUID) ([]SeasonFixturesRow, error) {
	rows, err := q.db.Query(ctx, seasonFixtures, seasonID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SeasonFixturesRow
	for rows.Next() {
		var i SeasonFixturesRow
		if err := rows.Scan(
			&i.Matchday,
			&i.ID,
			&i.Kickoff,
			&i.Status,
			&i.Exception,
			&i.HomeID,
			&i.HomeName,
			&i.AwayID,
			&i.AwayName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const seasonTeamRefs = `-- name: SeasonTeamRefs :many
SELECT DISTINCT r.external_id, t.id, t.name
FROM matchdays m
JOIN fixtures f ON f.matchday_id = m.id
JOIN teams t ON t.id IN (f.home_team_id, f.away_team_id)
JOIN provider_refs r ON r.entity = 'team' AND r.entity_id = t.id AND r.provider = $2
WHERE m.season_id = $1
ORDER BY r.external_id
`

type SeasonTeamRefsParams struct {
	SeasonID uuid.UUID
	Provider string
}

type SeasonTeamRefsRow struct {
	ExternalID string
	ID         uuid.UUID
	Name       string
}

// The provider refs of the teams that play in a season, for fetching their squads.
func (q *Queries) SeasonTeamRefs(ctx context.Context, arg SeasonTeamRefsParams) ([]SeasonTeamRefsRow, error) {
	rows, err := q.db.Query(ctx, seasonTeamRefs, arg.SeasonID, arg.Provider)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SeasonTeamRefsRow
	for rows.Next() {
		var i SeasonTeamRefsRow
		if err := rows.Scan(&i.ExternalID, &i.ID, &i.Name); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const settingsHead = `-- name: SettingsHead :one
SELECT league_id, seq, canonical_json, sha256, prev_sha256, schema, engine, effective_from_matchday, author, reason, created_at FROM settings_versions WHERE league_id = $1 ORDER BY seq DESC LIMIT 1
`

func (q *Queries) SettingsHead(ctx context.Context, leagueID uuid.UUID) (SettingsVersion, error) {
	row := q.db.QueryRow(ctx, settingsHead, leagueID)
	var i SettingsVersion
	err := row.Scan(
		&i.LeagueID,
		&i.Seq,
		&i.CanonicalJson,
		&i.Sha256,
		&i.PrevSha256,
		&i.Schema,
		&i.Engine,
		&i.EffectiveFromMatchday,
		&i.Author,
		&i.Reason,
		&i.CreatedAt,
	)
	return i, err
}
